import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student(student_id=last, last_name=last, first_name=first, section="A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.pupils = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Adler", "Sam"),
        ]

    def test_sorted_and_split(self):
        lines = seating_rows(self.pupils, 2)
        self.assertEqual(lines[0], "Row 1: Adler, Sam | Dunmere, Piet")
        self.assertEqual(lines[1], "Row 2: Halloway, Juno")

    def test_bad_seat_count(self):
        self.assertRaises(ValueError, seating_rows, self.pupils, 0)
        self.assertRaises(ValueError, seating_rows, self.pupils, -1)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
